options.styles:
.tn-active-issues-wrapper {
  display: flex;
  flex-direction: column;
  width: 100%;
  box-sizing: border-box;
}

.tn-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  width: 100%;
}

.tn-header-title {
  font-size: 11.5px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tn-view-all-btn {
  font-size: 12px;
  font-weight: 600;
  color: #38bdf8;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  border-radius: 6px;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.25);
  transition: all 0.2s ease;
}

.tn-view-all-btn:hover {
  background: rgba(56, 189, 248, 0.16);
  border-color: rgba(56, 189, 248, 0.45);
}

.tn-cards-container {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
  box-sizing: border-box;
  padding: 0;
}

.tn-card {
  flex: 1 1 calc(25% - 12px);
  min-width: 260px;
  max-width: 100%;
  border-radius: 8px;
  padding: 12px 14px;
  box-sizing: border-box;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tn-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6);
}

.tn-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tn-badge-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tn-icon-circle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  font-size: 10px;
}

.tn-severity-title {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.tn-metric-callout {
  font-size: 13.5px;
  font-weight: 700;
}

.tn-headline {
  font-size: 12.5px;
  font-weight: 700;
  color: #f8fafc;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tn-details-grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  background: rgba(15, 23, 42, 0.65);
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.tn-detail-row {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
}

.tn-detail-label {
  color: #94a3b8;
  width: 60px;
  flex-shrink: 0;
}

.tn-detail-val {
  color: #e2e8f0;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-weight: 600;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: right;
}

.tn-stats-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 10px;
  background: rgba(255, 255, 255, 0.03);
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.tn-stat-item {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
}

.tn-stat-label {
  color: #94a3b8;
  font-weight: 600;
}

.tn-stat-val {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-weight: 700;
  color: #e2e8f0;
}

.tn-card-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  margin-top: auto;
}

.tn-action-btn {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.04);
  transition: all 0.2s ease;
}

.tn-action-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

.tn-healthy-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-radius: 8px;
  border: 1px solid rgba(16, 185, 129, 0.3);
  background: linear-gradient(180deg, rgba(16, 185, 129, 0.08) 0%, rgba(15, 23, 42, 0.5) 100%);
  width: 100%;
  box-sizing: border-box;
}

.tn-healthy-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tn-healthy-icon {
  font-size: 18px;
}

.tn-healthy-text-group {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.tn-healthy-title {
  font-size: 13px;
  font-weight: 700;
  color: #10b981;
}

.tn-healthy-desc {
  font-size: 12px;
  color: #94a3b8;
}

.tn-view-all-btn {
  font-size: 12px;
  font-weight: 600;
  color: #38bdf8;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  border-radius: 6px;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.25);
  transition: all 0.2s ease;
}

.tn-view-all-btn:hover {
  background: rgba(56, 189, 248, 0.16);
  border-color: rgba(56, 189, 248, 0.45);
}

options.afterRender:
const el = context.element;
const btns = el.querySelectorAll('.tn-view-all-btn, .tn-action-btn');
if (btns && context.grafana && typeof context.grafana.replaceVariables === 'function') {
  btns.forEach(b => {
    const href = b.getAttribute('href');
    if (href) {
      b.setAttribute('href', context.grafana.replaceVariables(href));
    }
  });
}

// Auto-adjust panel height: slim (54px) when healthy, full (310px) when anomalies exist
const gridItem = el.closest('.react-grid-item');
if (gridItem && gridItem.parentElement) {
  const hasCards = el.querySelectorAll('.tn-card').length > 0 || el.querySelectorAll('.tn-active-issues-wrapper').length > 0;
  const parent = gridItem.parentElement;
  const allItems = Array.from(parent.children);
  const myIndex = allItems.indexOf(gridItem);

  const fullHeight = 310;
  const slimHeight = 54;
  const targetHeight = hasCards ? fullHeight : slimHeight;
  const delta = targetHeight - fullHeight;

  gridItem.style.height = targetHeight + 'px';

  for (let i = myIndex + 1; i < allItems.length; i++) {
    const item = allItems[i];
    if (!item.dataset.origY) {
      const transform = item.style.transform || '';
      const m = transform.match(/translate(?:3d)?\(\s*(-?[\d.]+)px\s*,\s*(-?[\d.]+)px/);
      if (m) {
        item.dataset.origX = m[1];
        item.dataset.origY = m[2];
        item.dataset.is3d = transform.includes('translate3d') ? '1' : '0';
      } else if (item.style.top) {
        item.dataset.origY = parseFloat(item.style.top);
      }
    }
    if (item.dataset.origY) {
      const origY = parseFloat(item.dataset.origY);
      const newY = origY + delta;
      const x = item.dataset.origX || '0';
      if (item.dataset.is3d === '1') {
        item.style.transform = `translate3d(${x}px, ${newY}px, 0px)`;
      } else if (item.dataset.origX) {
        item.style.transform = `translate(${x}px, ${newY}px)`;
      } else {
        item.style.top = newY + 'px';
      }
    }
  }
}
